"""Configure the Android manifest generated by Flutter."""

from pathlib import Path

manifest = Path(__file__).resolve().parents[1] / "app/android/app/src/main/AndroidManifest.xml"
content = manifest.read_text(encoding="utf-8")
template = '    <application\n        android:label="apply_to_anything"'
configured = (
    '    <uses-permission android:name="android.permission.INTERNET" />\n'
    '    <application\n'
    '        android:usesCleartextTraffic="true"\n'
    '        android:label="ApplyToAnything"'
)
if configured not in content:
    if template not in content:
        raise SystemExit("The Flutter Android manifest template has changed")
    manifest.write_text(content.replace(template, configured, 1), encoding="utf-8")
